document.addEventListener("DOMContentLoaded",()=>{const e=document.documentElement,t=document.getElementById("themeToggle"),d=["system","light","dark"];let n=0,m=d[n];const a=()=>{const e="system"===m?"system (default)":m;t.setAttribute("aria-label",`Theme: ${e}`),t.title=`Theme: ${e}`};e.dataset.themeMode=m,a(),t.hidden=!1,t.addEventListener("click",()=>{n=(n+1)%d.length,m=d[n],e.dataset.themeMode=m,"system"===m?delete e.dataset.theme:e.dataset.theme=m,a()}),document.getElementById("emailPopupOpen").addEventListener("click",()=>{window.prompt("Email:",["aymenadvance","@","gmail.com"].join(""))})});